import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.model_selection import StratifiedKFold
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Check if any feature shows significant association with outcome
    effects = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'derived':
            continue  # Skip derived features
        x = feats.x[:, i]
        y = feats.y
        # Welch's t-test for mean difference
        mean1 = np.mean(x[y==1])
        mean0 = np.mean(x[y==0])
        diff = mean1 - mean0
        t_stat, p_val = stats.ttest_ind(x[y==1], x[y==0], equal_var=False)
        auc = roc_auc_score(y, x) if len(np.unique(y)) > 1 else 0.5
        effects.append((fid, diff, abs(t_stat), p_val, auc))

    # Sort by effect size and statistical significance
    effects.sort(key=lambda x: (-abs(x[1]), -x[2]))

    # Check for correlation among top features to avoid near-duplicates
    top_fids = [f[0] for f in effects[:10]]
    correlations = {}
    for i, f1 in enumerate(top_fids):
        for j, f2 in enumerate(top_fids[i+1:], i+1):
            col1 = feats.column(f1)
            col2 = feats.column(f2)
            corr = np.corrcoef(feats.x[:, col1], feats.x[:, col2])[0,1]
            if abs(corr) >= 0.6:
                correlations[(f1, f2)] = corr

    # If no strong associations found, return empty design
    if not effects or max(abs(e[1]) for e in effects) < 0.5:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Select top features based on effect sizes, avoiding near-duplicates
    selected = []
    used_fids = set()

    for f in effects:
        fid = f[0]
        # Check if this feature is correlated with any already selected
        is_duplicate = False
        for selected_fid in selected:
            if (selected_fid, fid) in correlations or (fid, selected_fid) in correlations:
                is_duplicate = True
                break

        if not is_duplicate and fid not in used_fids:
            selected.append(fid)
            used_fids.add(fid)
            if len(selected) >= MAX_DRIVERS:
                break

    # Check for stratum consistency
    strata_consistent = True
    if len(set(feats.stratum)) > 1:
        strata = list(set(feats.stratum))
        for s in strata:
            mask = np.array([s_ == s for s_ in feats.stratum])
            s_x = feats.x[mask]
            s_y = feats.y[mask]
            if len(s_y) < 10:
                continue  # Too few samples
            for fid in selected:
                col = feats.column(fid)
                x = s_x[:, col]
                try:
                    t_stat, p_val = stats.ttest_ind(x[s_y==1], x[s_y==0], equal_var=False)
                    if p_val > 0.05:
                        strata_consistent = False
                        break
                except:
                    strata_consistent = False
                    break
            if not strata_consistent:
                break

    # Final decision
    if strata_consistent and selected:
        drivers = tuple(selected[:MAX_DRIVERS])
    else:
        drivers = ()

    # Build regression components
    columns = tuple(selected[:MAX_DRIVERS])
    products = ()
    loadings = {fid: 1.0 for fid in columns}

    return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)

# Helper function for AUC calculation
def roc_auc_score(y_true, y_score):
    try:
        from sklearn.metrics import roc_auc_score as sk_auc
        return sk_auc(y_true, y_score)
    except ImportError:
        # Simple approximation if sklearn not available
        return 0.5
